#!/usr/bin/env python3\nfrom pathlib import Path\nimport sys, tempfile\nsys.path.insert(0,"/app")\nfrom PIL import Image\nimport lcd_generator as lg\nfrom render_shared import spark\n\nassert lg.numeric("89.3 %")==89.3\nassert lg.numeric("12,5 KB/s")==12.5\ndef frac(value,mn,mx): return max(0.0,min(1.0,(lg.numeric(value)-lg.numeric(mn))/max(.000001,lg.numeric(mx)-lg.numeric(mn))))\nassert abs(frac("89.3 %",0,100)-0.893)<1e-9\n\ne={"type":"badge","label":"truenas_system_status","detailLabel":"truenas_system_status_detail","x":10,"y":20,"w":220,"h":100,"size":32,"detailSize":20,"detailGap":8,"align":"center"}\ns=lg.status_sensors(e)\nassert len(s)==2\n# main and detail have separate line boxes, not the full 100px status box\nassert s[0]["height"] < 60, s[0]\nassert s[1]["y"] > s[0]["y"]+20, s\n\nim=Image.new("RGBA",(320,120),(0,0,0,255))\nvals=[{"value":20},{"value":40},{"value":60},{"value":80}]\nspark(im,(0,0,200,100),vals,"#F29A49",100,20)\nassert im.getbbox() is not None\nprint("v0.8.10 renderer parity selftest: OK")\n